// Some portions generated by Codex
import assert from "node:assert/strict";
import test from "node:test";
import { scoped } from "../../../main/frontend/graph-explorer/rdf-vocabulary.ts";
import { statementAnnotationsQuery } from "../../../main/frontend/graph-explorer/statement-details.ts";

test("independent all-graph scans can use distinct internal graph variables", () => {
  const pattern = "?s ?p ?o .";
  assert.equal(scoped(pattern, "all", "__annotationGraph"),
    `{ ${pattern} } UNION { GRAPH ?__annotationGraph { ${pattern} } }`);
  assert.equal(scoped(pattern, "all"), `{ ${pattern} } UNION { GRAPH ?__graph { ${pattern} } }`);
  assert.equal(scoped(pattern, "default", "__annotationGraph"), pattern);
  assert.equal(scoped(pattern, "urn:g", "__annotationGraph"), `GRAPH <urn:g> { ${pattern} }`);
  assert.throws(() => scoped(pattern, "all", "invalid } UNION { ?s ?p ?o"), /graph variable/i);
});

test("annotation identification and optional properties scan all graphs independently", () => {
  const statement = { subject: "<urn:a>", predicate: "<urn:p>", object: "<urn:b>" };
  const all = statementAnnotationsQuery(statement, "all", true);
  assert.match(all, /GRAPH \?__annotationGraph \{ \?about \?property \?value/);
  assert.match(all, /GRAPH \?__graph \{ \?about <[^>]+reifies>/);
  assert.doesNotMatch(statementAnnotationsQuery(statement, "urn:g", true), /__annotationGraph/);
});
